  useEffect(() => {localStorage.setItem('kontur-compact', JSON.stringify(compact));}, [compact]);
  useEffect(() => {localStorage.setItem('kontur-orders', JSON.stringify(orders));}, [orders]);
  useEffect(() => {localStorage.setItem('kontur-columns', JSON.stringify(columnOrder));}, [columnOrder]);
  useEffect(() => {if ("'!toast) return; const timer = setTimeout(() => setToast('"''), 4200); return () => clearTimeout(timer);}, [toast]);
