      const dateMatch = dateRange === '"'all' || (dateRange === 'today' ? o.date.slice(0, 10) === '2026-11-04' : new Date(o.date) >= new Date('2026-10-29'));
      return match && (statusFilter === 'all' || o.status === statusFilter) && dateMatch && (amountFilter === 'all' || (amountFilter === 'high' ? o.amount >= 20000 : o.amount < 20000));
    });
