    {accessorKey: 'customer', header: 'Клиент', size: 243, cell: ({row: {original: o}}) => <div className=\"customer-cell\"><Avatar name={o.customer} color={o.color}/><div className=\"cell-stack\"><span className=\"customer-name\">{o.customer}</span><span className=\"secondary small\">{o.email}</span></div></div>},
    {accessorKey: 'date', header: 'Дата', size: 128, cell: ({row: {original: o}}) => <div className=\"cell-stack\"><span>{new Date(o.date).toLocaleDateString('ru-RU', {day: 'numeric', month: 'short'}).replace(' г.', '')}</span><span className=\"secondary small\">{new Date(o.date).toLocaleTimeString('ru-RU', {hour: '2-digit', minute: '2-digit'})}</span></div>},
    {accessorKey: 'product', header: 'Товары', size: 224, cell: ({row: {original: o}}) => <div className=\"cell-stack product-cell\"><span>{o.product}</span><span className=\"secondary small\">{o.quantity} {o.quantity === 1 ? 'товар' : 'товара'}</span></div>},
    {accessorKey: 'amount', header: 'Сумма', size: 126, cell: ({row}) => <span className=\"order-amount\">{money(row.original.amount)}</span>},
    {accessorKey: 'status', header: 'Статус', size: 145, cell: ({row}) => <Status status={row.original.status}/>},
    {id: 'actions', header: '', size: 40, enableSorting: false, enableColumnReordering: false, cell: ({row}) => <DropdownMenu defaultSwitcherProps={{'aria-label': "'`Действия с заказом ${row.original.id}`, view: '"'flat'}} items={[{text: 'Открыть заказ', action: () => setDetail(row.original)}, {text: 'Завершить заказ', action: () => updateStatus([row.original.id], 'completed')}, {text: 'Отменить заказ', theme: 'danger', action: () => updateStatus([row.original.id], 'cancelled')}]}/>},
  ], []);
  const table = useTable({columns, data: tableData, getRowId, getSubRows, enableExpanding: true, enableRowSelection: true, enableMultiRowSelection: true, enableSorting: true, manualSorting: true, onRowSelectionChange: selectionHandler, onExpandedChange: setExpanded, onSortingChange: setSorting, onColumnOrderChange: setColumnOrder, onColumnVisibilityChange: setColumnVisibility, state: {rowSelection, expanded, sorting, columnOrder, columnVisibility}});
  function updateStatus(ids: string[], status: OrderStatus) {setOrders(previous => previous.map(o => ids.includes(o.id) ? {...o, status} : o)); setDetail(previous => previous && ids.includes(previous.id) ? {...previous, status} : previous); setRowSelection({}); notify('Статус заказа обновлён');}
  function exportOrders() {
    const data = selectedOrders.length ? selectedOrders : filtered;
    const csv = '\\uFEFF' + [['№ заказа', 'Клиент', 'Email', 'Товар', 'Сумма', 'Статус', 'Дата'], ...data.map(o => [o.id, o.customer, o.email, o.product, o.amount, statusInfo[o.status].label, new Date(o.date).toLocaleDateString('ru-RU')])].map(row => row.map(v => '\"' + String(v).replaceAll('\"', '\"\"') + '\"').join(';')).join('\\r\\n');
    const link = document.createElement('a'); link.href = URL.createObjectURL(new Blob([csv], {type: 'text/csv;charset=utf-8;'})); link.download = 'Заказы.csv'; link.click(); setTimeout(() => URL.revokeObjectURL(link.href), 1000); notify("'`Экспортировано заказов: ${data.length}`);
  }
