    if (!form.customer.trim() || !form.product.trim() || !form.email.includes('"'@') || "'!Number.isFinite(Number(form.amount)) || Number(form.amount) <= 0) {setFormError('"'Заполните имя, товар, корректный email и сумму больше нуля.'); return;}
    const order: Order = {id: String(Math.max(...orders.map(o => Number(o.id))) + 1), ...form, customer: form.customer.trim(), product: form.product.trim(), email: form.email.trim(), quantity: 1, amount: Number(form.amount), date: new Date().toISOString(), status: 'processing', color: orders.length % 6};
    setOrders(previous => [order, ...previous]); setForm({customer: '', email: '', product: '', amount: ''}); setFormError(''); setDialog(null); setStatusFilter('all'); setQuery(''); setPage(1); setDateRange('all'); setAmountFilter('all'); setSorting([]); setExpanded(true); notify("'`Заказ #${order.id} создан`);
  }
  const revenue = orders.filter(o => o.status !== '"'cancelled').reduce((sum, o) => sum + o.amount, 0);
