    {label: 'В обработке', value: counts.processing, icon: Clock, change: "'`${counts.shipping} в доставке`, note: '"'требуют внимания', tone: 'orange', bars: [55, 70, 47, 65, 40, 58, 66, 45, 60, 50, 40, 54]},
    {label: 'Выручка', value: money(revenue), icon: CircleDollar, change: '+18,4%', note: 'за последний месяц', tone: 'green', bars: [20, 35, 30, 48, 40, 60, 52, 65, 78, 70, 88, 100]},
    {label: 'Средний чек', value: money(Math.round(revenue / (orders.length - counts.cancelled || 1))), icon: ReceiptIcon, change: '+4,9%', note: 'за последний месяц', tone: 'green', bars: [45, 30, 55, 45, 60, 52, 74, 64, 80, 70, 90, 85]},
  ];
  const pageTitle = navItems.find(i => i.id === activePage)?.title || 'Заказы';
  return <AsideHeader className=\"app-shell\" compact={compact} onChangeCompact={setCompact} collapseTitle=\"Свернуть меню\" expandTitle=\"Развернуть меню\" hideSectionDividers
