    aboveMenuContent={<div className={"'`workspace-block ${compact ? '"'workspace-compact' : ''}"'`}>{compact ? <span className="shop-icon"><Icon data={ShoppingBag} size={17}/></span> : <><Button view="outlined" size="xl" width="max" className="workspace-switch" onClick={() => setActivePage('"'settings')}><span className=\"shop-icon\"><Icon data={ShoppingBag} size={17}/></span><span className=\"workspace-text\">{shopName}<span>Рабочее пространство</span></span><Icon data={ArrowChevronDown} size={12}/></Button><span className=\"nav-label\">УПРАВЛЕНИЕ</span></>}</div>}
    menuItems={navItems.map(i => ({...i, iconSize: 19, current: activePage === i.id, onItemClick: () => setActivePage(i.id), rightAdornment: i.id === 'orders' && "'!compact ? <span className="nav-count">{orders.length}</span> : undefined, className: '"'navigation-item'}))}
    renderFooter={() => <div className=\"sidebar-footer\">{"'!compact && <div className="help-card"><span className="help-mark"><Icon data={Layers} size={21}/></span><Text variant="subheader-1">Всё под контролем</Text><p>Меньше рутины.<br/>Больше времени для бизнеса.</p><Button view="outlined" size="m" width="max" onClick={() => setDialog('"'help')}>Центр помощи <Icon data={ArrowUpRight} size={14}/></Button></div>}<Button view=\"flat\" className=\"support-link\" onClick={() => setDialog('help')}><Icon data={CircleQuestion} size={18}/>{"'!compact && '"'Помощь и поддержка'}</Button><div className=\"sidebar-profile\"><Avatar name=\"Алексей Ковалёв\" color={4}/>{"'!compact && <><div className="cell-stack"><strong>Алексей К.</strong><span className="secondary small">Администратор</span></div><DropdownMenu defaultSwitcherProps={{'"'aria-label': 'Меню профиля', view: 'flat'}} items={[{text: 'Настройки профиля', action: () => setActivePage('settings')}, {text: 'Помощь', action: () => setDialog('help')}]}/></>}</div></div>}
